grid = [[6,8,8,8,8,1,8,8,8,8]] + [[8]*10 for _ in range(3)] + [[8,8,8,8,8,8,8,1,1,1],[1,8,8,8,8,8,8,1,1,1],[1,1,8,8,8,8,8,8,8,8],[8]*10,[8]*10,[8,8,8,8,8,1,1,1,8,8]]
h,w=len(grid),len(grid[0])
# Select 1-components touching the outer frame; dilate them by one 8-neighbor step.
seen=set(); selected=set()
for r in range(h):
  for c in range(w):
    if grid[r][c]==1 and (r,c) not in seen:
      stack=[(r,c)]; comp=set(); seen.add((r,c))
      while stack:
        y,x=stack.pop(); comp.add((y,x))
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
          yy,xx=y+dy,x+dx
          if 0<=yy<h and 0<=xx<w and grid[yy][xx]==1 and (yy,xx) not in seen:
            seen.add((yy,xx)); stack.append((yy,xx))
      if any(y in (0,h-1) or x in (0,w-1) for y,x in comp):
        selected |= comp
out=[row[:] for row in grid]
for r in range(h):
  for c in range(w):
    if grid[r][c]==8 and (r in (0,h-1) or c in (0,w-1) or any((r+dy,c+dx) in selected for dy in (-1,0,1) for dx in (-1,0,1) if dy or dx)):
      out[r][c]=7
print('\n'.join(str(row) for row in out))
